<?php require_once __DIR__.'/../config/auth.php';require_admin();$loans=db()->query('SELECT e.*,u.nome aluno,l.titulo FROM emprestimos e JOIN usuarios u ON u.id=e.usuario_id JOIN livros l ON l.id=e.livro_id ORDER BY e.created_at DESC')->fetchAll();$pageTitle='Empréstimos';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><div style="text-align:right"><a class="btn" href="<?=base_url('admin/novo-emprestimo.php')?>">+ Novo empréstimo</a></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Livro</th><th>Retirada</th><th>Previsão</th><th>Status</th></tr></thead><tbody><?php foreach($loans as $l):$status=loan_status($l)?><tr><td><?=e($l['aluno'])?></td><td><?=e($l['titulo'])?></td><td><?=date('d/m/Y',strtotime($l['data_emprestimo']))?></td><td><?=date('d/m/Y',strtotime($l['data_prevista_devolucao']))?></td><td><span class="badge <?=$status==='atrasado'?'off':''?>"><?=e(ucfirst($status))?></span></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
